 function saveSettings(){if(!projectId)return;settings[projectId]={count,minCells,ratioX,ratioY,canvasHidden,canvasIndex,rowHeights,tileSizes,slots:[...slots],thumbnails,active,side,focus,rail:root.style.getPropertyValue('--rail-width'),ai:root.style.getPropertyValue('--ai-width')};const snapshot=JSON.stringify(settings);if(snapshot===lastSaved)return;lastSaved=snapshot;clearTimeout(saveTimer);saveTimer=setTimeout(()=>native.set({browserShell:settings}).catch(e=>status(e.message)),180)}
 async function syncProject(){const id=project();if(!id)throw Error('Откройте проект на холсте');if(id===projectId)return;if(pending)await pending;pending=(async()=>{data=await call('project',{id});projectId=id;active='';side='';slots=[CANVAS,'','',''];focus=-1;const p=settings[id]||{};canvasHidden=!!p.canvasHidden;canvasIndex=Number.isInteger(p.canvasIndex)?Math.max(0,p.canvasIndex):0;tileSizes=Object.fromEntries(Object.entries(p.tileSizes||{}).filter(([key,v])=>key&&v&&Number.isFinite(v.w)&&Number.isFinite(v.h)).map(([key,v])=>[key,{...v,w:Math.max(.15,Math.min(1,v.w)),h:Math.max(.15,Math.min(1,v.h))}]));rowHeights=p.rowHeights&&typeof p.rowHeights==='object'?p.rowHeights:{};count=[1,2,3,4].includes(p.count)?p.count:4;minCells=Number.isInteger(p.minCells)?Math.max(0,Math.min(4,p.minCells)):count;ratioX=Math.max(.2,Math.min(.8,Number(p.ratioX)||.5));ratioY=Math.max(.2,Math.min(.8,Number(p.ratioY)||.5));if(Array.isArray(p.slots))slots=p.slots.filter(x=>typeof x==='string');eyeIds=new Set(data.contextScope||[]);thumbnails=!!p.thumbnails;active=p.active||'';side=p.side==='@chat'?'':p.side||'';focus=Number.isInteger(p.focus)&&p.focus>=0&&p.focus<count?p.focus:-1;root.style.setProperty('--rail-width',Math.max(80,Math.min(280,parseFloat(p.rail)||80))+'px');root.style.setProperty('--ai-width',Math.max(260,Math.min(700,parseFloat(p.ai)||340))+'px')})();try{await pending}finally{pending=null}}
